llamadas.contenido:
{
  "title": "Historia de Usuario (HU) para reservar un ejemplar en la Biblioteca Municipal de Villaficticia",
  "role": "Persona socia de la Biblioteca Municipal de Villaficticia",
  "action": "Reservar un ejemplar desde la web para recogerlo en el mostrador",
  "benefit": "Acceder a un ejemplar de libro en la sede de recogida con garantía de disponibilidad y seguimiento",
  "description": "La persona socia quiere realizar una reserva en la Biblioteca Municipal de Villaficticia, solicitando un ejemplar desde la web con el objetivo de recogerlo en el mostrador. La reserva debe cumplir con las reglas de reservas, incluyendo límites de reservas activas, estados de reserva y procedimientos de notificación.",
  "business_goal": "Realizar una reserva de un título en la sede de recogida, con un máximo de 3 reservas activas, con seguimiento de la disponibilidad y notificación de caducidad.",
  "scope_includes": [
    "La solicitud de reserva desde la web",
    "El proceso de verificación de la reserva en el sistema",
    "El cálculo de la disponibilidad y notificación de caducidad",
    "La cancelación de reserva si se decide no recogerlo"
  ],
  "scope_excludes": [
    "El acceso a la biblioteca en horario no señalado",
    "El uso de reservas por fuera de la biblioteca",
    "Las reservas de obras de referencia ni de títulos ya en préstamo"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Solicitud de reserva",
      "given": [
        "La persona socia accede a la web de la Biblioteca Municipal de Villaficticia",
        "La persona socia selecciona el título que deseas reservar"
      ],
      "when": [
        "La persona socia está en la cola de reservas",
        "La persona socia ha completado la solicitud de reserva"
      ],
      "then": [
        "Se muestra la información de la reserva en el sistema",
        "Se genera el estado de la reserva como 'Pendiente'"
      ]
    },
    {
      "id": "CA-02",
      "title": "Verificación de reserva",
      "given": [
        "El sistema verifica que la persona socia tiene carné vigente",
        "El sistema verifica que no hay sanción activa"
      ],
      "when": [
        "Antes de la reserva",
        "Durante la reserva"
      ],
      "then": [
        "Se confirma que la reserva es válida",
        "Se asigna el primer ejemplar disponible del título"
      ]
    },
    {
      "id": "CA-03",
      "title": "Notificación de caducidad",
      "given": [
        "El ejemplar se bloquea en la sede de recogida durante 48 horas",
        "La persona socia está en la cola de reservas"
      ],
      "when": [
        "La reserva se crea",
        "La persona socia no recoge el ejemplar en el plazo de 48 horas"
      ],
      "then": [
        "Se notifica a la persona socia del estado de la reserva",
        "La reserva se marca como 'Caducada'"
      ]
    },
    {
      "id": "CA-04",
      "title": "Cancelación de reserva",
      "given": [
        "La persona socia desea cancelar la reserva",
        "La reserva no se ha recogido"
      ],
      "when": [
        "Antes de recoger el ejemplar",
        "Después de la caducidad"
      ],
      "then": [
        "La reserva se anula",
        "Se libera el ejemplar y se elimina de la cola"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Solo pueden reservar las personas socias con carné vigente y sin sanción activa."
    },
    {
      "id": "RN-RES-02",
      "description": "Cada persona socia puede tener un máximo de 3 reservas activas."
    },
    {
      "id": "RN-RES-03",
      "description": "La reserva se hace sobre un título y una sede de recogida. El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "id": "RN-RES-04",
      "description": "Las reservas de un mismo título se atienden por estricto orden de llegada (cola de reservas)."
    },
    {
      "id": "RN-RES-05",
      "description": "Cuando el ejemplar queda disponible en la sede de recogida, se bloquea durante 48 horas para la persona socia que encabeza la cola, y se le notifica."
    },
    {
      "id": "RN-RES-06",
      "description": "Si el ejemplar no se recoge en esas 48 horas, la reserva caduca, el ejemplar pasa a la siguiente persona de la cola y la reserva cuenta como 'no recogida' a efectos de RN-SAN-04."
    },
    {
      "id": "RN-RES-07",
      "description": "La persona socia puede cancelar una reserva en cualquier momento antes de recogerla, sin penalización."
    },
    {
      "id": "RN-RES-08",
      "description": "Mientras exista una reserva pendiente sobre un título, ningún préstamo de ese título puede renovarse."
    },
    {
      "id": "RN-RES-09",
      "description": "No se pueden reservar obras de referencia ni títulos de los que la persona socia ya tenga un ejemplar en préstamo."
    },
    {
      "id": "RN-RES-10",
      "description": "Las personas con carné infantil pueden reservar solo títulos de la colección infantil y juvenil, con el mismo máximo de 3 reservas activas."
    }
  ],
  "assumptions": [
    "La persona socia tiene acceso a la web de la Biblioteca Municipal de Villaficticia.",
    "El sistema verifica la validez de la reserva antes de su creación.",
    "La persona socia puede cancelar la reserva antes de recogerlo."
  ],
  "constraints": [
    "No se pueden reservar obras de referencia ni títulos ya en préstamo.",
    "La persona socia no puede tener más de 3 reservas activas en cualquier momento."
  ],
  "dependencies": [
    "El sistema debe verificar la validez de la reserva antes de su creación.",
    "El sistema debe notificar a la persona socia cuando la reserva se bloquea o caduca."
  ],
  "alternate_flows": [
    "Si la persona socia no recoge el ejemplar en el plazo de 48 horas, la reserva se vuelve a la cola y se le notifica.",
    "Si la persona socia desea cancelar la reserva, puede hacerlo en cualquier momento antes de recogerlo."
  ],
  "exceptions": [
    "Las reservas no recogidas reiteradas se manejan con alternativas específicas (Alternativa A y B)."
  ],
  "related_features": [
    "La capacidad de reservar un máximo de 3 reservas activas.",
    "El sistema de notificación de caducidad.",
    "La capacidad de cancelación de reserva."
  ],
  "priority": "Should",
  "sources": [
    {
      "kind": "rag",
      "ref": "DOC-02",
      "excerpt": "Solo pueden reservar las personas socias con carné vigente y sin sanción activa que impida reservar (ver RN-SAN-03 y RN-SAN-04 en DOC-03)."
    },
    {
      "kind": "rag",
      "ref": "DOC-06",
      "excerpt": "La reserva se hace sobre un título y una sede de recogida. El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "kind": "rag",
      "ref": "DOC-01",
      "excerpt": "Cada persona socia puede tener en préstamo simultáneo un máximo de 8 ejemplares."
    },
    {
      "kind": "rag",
      "ref": "DOC-20",
      "excerpt": "Se acuerda que el aviso de reserva caducada informe del número de reservas no recogidas acumuladas, para que la persona socia pueda evitar la sanción."
    }
  ],
  "open_questions": [
    "¿Cómo se maneja la cancelación de reserva en casos de no recogida?",
    "¿Qué pasa si la persona socia no recoge el ejemplar y la reserva se vuelve a la cola?",
    "¿Qué se hace con las reservas no recogidas en casos de repetición?"
  ]
}
